const systemPrompt = "You are a forensic Odoo accounting auditor for Ride Electric Brisbane EOFY preparation.\n\nSCOPE (mandatory)\n- Business: Ride Electric Brisbane only\n- Odoo company_id: 4\n- Financial year: 2024-07-01 to 2025-06-30 (Australia/Brisbane)\n- Do not generalise to other Ride Electric entities unless data explicitly supports it.\n\nMINDSET\nOdoo accounting, POS, stock, products, payments, and reconciliation form a connected transaction graph. Reconstruct that graph, test completeness, and identify anomalies. Do not treat models as isolated tables.\n\nEVIDENCE RULES\n- Missing exported model or zero rows = extraction gap, NOT proof of no issue.\n- Do not run financial conclusions without account_move_line.\n- Do not run POS conclusions without pos_order, pos_order_line, and pos_payment.\n- Sanitised partner/user labels (ENTITY_*) are for grouping only, not re-identification.\n- State uncertainty when data is insufficient.\n\nOUTPUT FORMAT (JSON only, no markdown fences)\n{\n  \"scope\": { \"company_id\": 4, \"fy_start\": \"2024-07-01\", \"fy_end\": \"2025-06-30\" },\n  \"extraction_gaps\": [ { \"model\": \"\", \"impact\": \"\", \"blocks_tests\": [] } ],\n  \"completeness\": [ { \"check\": \"\", \"status\": \"pass|fail|blocked\", \"evidence\": \"\", \"severity\": \"critical|high|medium|low\" } ],\n  \"anomalies\": [\n    {\n      \"id\": \"A001\",\n      \"category\": \"accounting|pos|bank|gst|stock|audit_trail|structure\",\n      \"severity\": \"critical|high|medium|low\",\n      \"title\": \"\",\n      \"description\": \"\",\n      \"models_involved\": [],\n      \"sample_record_ids\": [],\n      \"recommended_action\": \"\",\n      \"eofy_impact\": \"\"\n    }\n  ],\n  \"eofy_readiness\": {\n    \"status\": \"ready|blocked|review_required\",\n    \"summary\": \"\",\n    \"priority_fixes_before_submission\": []\n  }\n}\n\nPrioritise anomalies that would block or misstate EOFY submission. Be specific with record IDs and amounts where present in the payload.\n";

const input = $input.first().json;
const snapshotId = input.snapshot_id;
if (!snapshotId) throw new Error('snapshot_id required');

const reportRoot = path.join(scope.export_paths.report_root, snapshotId);
const summaryPath = path.join(reportRoot, 'claude_readiness_summary.json');
const payloadPath = path.join(reportRoot, 'claude_payload_all.jsonl');

const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf8'));
const payloadLines = fs.readFileSync(payloadPath, 'utf8').split('\n').filter(l => l.trim());

// Token budget: sample up to 800 records stratified by model
const byModel = {};
for (const line of payloadLines) {
  const row = JSON.parse(line);
  const key = row._sanitisation?.model || 'unknown';
  if (!byModel[key]) byModel[key] = [];
  if (byModel[key].length < 40) byModel[key].push(row);
}
const samplePayload = Object.values(byModel).flat();

const userPayload = {
  scope: {
    company_id: scope.company_id,
    business: scope.business,
    fy_start: scope.financial_year_start,
    fy_end: scope.financial_year_end,
    caveats: scope.handover_caveats,
  },
  readiness_summary: summary.summary,
  extraction_gaps: summary.extraction_gaps,
  audit_tests: auditTests,
  join_keys: joinKeys,
  model_summaries: summary.model_summaries,
  sample_records: samplePayload,
  note: 'Full dataset on n8n server; this payload is a stratified sample for anomaly detection.',
};

return [{
  json: {
    snapshot_id: snapshotId,
    report_root: reportRoot,
    anthropic_body: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 8192,
      system: systemPrompt,
      messages: [{
        role: 'user',
        content: JSON.stringify(userPayload),
      }],
    },
    user_payload_bytes: JSON.stringify(userPayload).length,
  }
}];

const fs = require('fs');
const path = require('path');

const prep = $('Prepare Claude audit request').first().json;
const api = $input.first().json;
const reportRoot = prep.report_root;

let text = '';
if (api.content && Array.isArray(api.content)) {
  text = api.content.map(c => c.text || '').join('');
} else if (typeof api.text === 'string') {
  text = api.text;
} else {
  text = JSON.stringify(api);
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch {
  parsed = { raw_text: text, parse_error: true };
}

const outPath = path.join(reportRoot, 'claude_anomaly_report.json');
fs.writeFileSync(outPath, JSON.stringify({
  snapshot_id: prep.snapshot_id,
  generated_at_utc: new Date().toISOString(),
  model: prep.anthropic_body.model,
  report: parsed,
}, null, 2));

return [{
  json: {
    ok: true,
    snapshot_id: prep.snapshot_id,
    report_path: outPath,
    eofy_status: parsed.eofy_readiness?.status || 'unknown',
    anomaly_count: Array.isArray(parsed.anomalies) ? parsed.anomalies.length : 0,
  }
}];
